insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_leisure','leisure time','noun','time when you are not working or studying and can relax or enjoy activities','[{"senseId":"leisure_1","meaning":"time when you are not working or studying and can relax or enjoy activities","acceptedParaphrases":["free time","spare time"],"masteryContexts":[{"contextId":"u1_01_leisure_meaning","text":"Many students use their leisure time to play sport or meet friends.","meaning":"time free for enjoyable activities","wrongMeanings":["time set aside for school lessons","hours spent travelling between places","a short pause between two tasks"]},{"contextId":"u1_01_leisure_paraphrase","text":"Longer working hours leave families with less leisure time than they had ten years ago.","meaning":"recreation time outside normal duties","wrongMeanings":["extra time added to the working week","the period needed to finish a job","rest taken after an illness"]}],"situationDistractors":["Our coach set a strict timetable for every hour of the training camp.","Students must finish their homework before they are allowed to use the gym.","The athletes spent the whole afternoon in a compulsory team meeting.","Her part-time job at the sports shop takes up most of her weekends."],"gapDistractors":[{"contextId":"u1_01_leisure_gap_meaning_sentence","answer":"leisure time","wrong":["homework","working hours","uniform"]},{"contextId":"u1_01_leisure_gap_x1","answer":"leisure time","wrong":["homework","school hours","rent"]},{"contextId":"u1_01_leisure_gap_x2","answer":"leisure time","wrong":["income","noise","crime"]}],"spellingErrors":["leisur time","lesiure time","liesure time","leasure time","leisuer time","lesure time"],"masteryPassages":[{"passageId":"u1_01_leisure_passage_1","contextId":"u1_01_leisure_gap_meaning_sentence","text":"After a long week of lessons and homework, Chen looks forward to Saturday. His ____ is the only part of the week when he can choose what to do, and he usually spends it cycling with friends.","answer":"leisure time"},{"passageId":"u1_01_leisure_passage_2","contextId":"u1_01_leisure_gap_x1","text":"Many workers now answer emails late at night. As a result, the boundary between work and ____ has almost disappeared, and people say they feel more tired.","answer":"leisure time"}],"contextDependentParaphrases":[],"wrongParaphrases":["working hours","homework time","study period"],"misleadingDistractors":["working hours","homework time","training time"]}]'::jsonb,'[]'::jsonb,'["leisure activity","leisure facilities"]'::jsonb,'live'),
('vocab_preference','preference','noun','a greater liking for one option than another','[{"senseId":"preference_1","meaning":"a greater liking for one option than another","acceptedParaphrases":["choice you favour","liking"],"masteryContexts":[{"contextId":"u1_02_preference_meaning","text":"The survey showed that most people have a strong preference for fresh food over tinned food.","meaning":"a liking for one option over another","wrongMeanings":["a rule about which food to buy","a belief that tinned food is unsafe","a habit of eating the same meals"]},{"contextId":"u1_02_preference_paraphrase","text":"When I booked the flight, the website asked whether I had a preference for a window or an aisle seat.","meaning":"a stronger wish for one choice than the rest","wrongMeanings":["a complaint about the seat that was booked","a rule about where passengers must sit","a request for more space on the flight"]}],"situationDistractors":["Our school rule says every student must take part in a team sport.","He chose swimming because there was no space left in the other classes.","The coach decided who would play in defence without asking the players.","She dislikes team games and avoids joining any of them."],"gapDistractors":[{"contextId":"u1_02_preference_gap_meaning_sentence","answer":"preference","wrong":["dislike","complaint","disagreement"]},{"contextId":"u1_02_preference_gap_x1","answer":"preference","wrong":["complaint","penalty","refund"]},{"contextId":"u1_02_preference_gap_x2","answer":"preference","wrong":["complaint","refund","discount"]}],"spellingErrors":["preferance","prefrence","prefference","preferrence","prefernce","preferense"],"wordFamilyForms":[{"form":"preference","partOfSpeech":"noun","example":"Most customers showed a clear preference for the cheaper trainers.","pedagogicallyUseful":true},{"form":"prefer","partOfSpeech":"verb","example":"Many teenagers prefer exercising with friends to training alone.","pedagogicallyUseful":true,"altExample":"Most of my classmates prefer playing outdoors when the weather is dry."},{"form":"preferable","partOfSpeech":"adjective","example":"For a short journey, cycling is preferable to taking the bus.","pedagogicallyUseful":true,"altExample":"A quiet training session is preferable to a rushed one before an exam."}],"masteryPassages":[{"passageId":"u1_02_preference_passage_1","contextId":"u1_02_preference_gap_meaning_sentence","text":"The café offered tea, coffee or hot chocolate. When the waiter asked about my ____, I said I would rather have tea than anything else.","answer":"preference"},{"passageId":"u1_02_preference_passage_2","contextId":"u1_02_preference_gap_x1","text":"Some students like to study alone, while others work better in groups. Teachers try to respect each student’s ____ whenever the timetable allows it.","answer":"preference"}],"contextDependentParaphrases":[],"wrongParaphrases":["rule you must follow","reason you give","result you expect"],"misleadingDistractors":["requirement","permission","result"]}]'::jsonb,'["prefer","preferable"]'::jsonb,'["personal preference","express a preference"]'::jsonb,'live'),
('vocab_avoid','avoid','verb','to stay away from something or prevent it from happening','[{"senseId":"avoid_1","meaning":"to stay away from something or prevent it from happening","acceptedParaphrases":["stay away from","prevent"],"masteryContexts":[{"contextId":"u1_03_avoid_meaning","text":"Try to avoid eating a big meal just before you swim.","meaning":"keep clear of something unwanted","wrongMeanings":["make sure something happens on time","stop other people from doing something","try something new for the first time"]},{"contextId":"u1_03_avoid_paraphrase","text":"The new bypass helps commuters avoid the busiest roads.","meaning":"deliberately stay away from something","wrongMeanings":["quickly drive along a particular route","officially close a road to the public","find the quickest way to a place"]}],"situationDistractors":["He ran straight into the crowded training area without checking.","His team looked for every chance to take risks in the final.","She tried a new sport every month to see which one she liked.","The coach warned him that the injury could get worse if he kept playing.","He walked straight towards the heavy traffic without looking, and he nearly caused an accident.","Their captain asked everyone to run towards the loudest, most crowded part of the stadium."],"gapDistractors":[{"contextId":"u1_03_avoid_gap_base_noun","answer":"avoid","wrong":["take","seek","welcome"]},{"contextId":"u1_03_avoid_gap_third_ing","answer":"avoids","wrong":["hopes","wants","expects"]},{"contextId":"u1_03_avoid_gap_past_noun","answer":"avoided","wrong":["calculated","reported","measured"]},{"contextId":"u1_03_avoid_gap_perfect_ing","answer":"avoided","wrong":["enjoyed","practised","resumed"]},{"contextId":"u1_03_avoid_gap_plural_ing","answer":"avoid","wrong":["enjoy","prefer","practise"]}],"spellingErrors":["aviod","avoyd","avoide","avoied","avode","avoidd"],"wordFamilyForms":[{"form":"avoid","partOfSpeech":"verb","example":"Careful players avoid unnecessary risks late in the match.","pedagogicallyUseful":true},{"form":"avoidance","partOfSpeech":"noun","example":"Regular stretching is an important part of injury avoidance.","pedagogicallyUseful":true,"altExample":"The avoidance of sugary drinks is part of the athletes’ diet plan."},{"form":"unavoidable","partOfSpeech":"adjective","example":"Some delays on long journeys are unavoidable.","pedagogicallyUseful":true,"altExample":"With so many teams entering, a few disappointments were unavoidable."}],"masteryPassages":[{"passageId":"u1_03_avoid_passage_1","contextId":"u1_03_avoid_gap_base_noun","text":"The motorway was full of traffic, so we took a country road to ____ the delays near the city. The journey was a little longer, but much more relaxing.","answer":"avoid"},{"passageId":"u1_03_avoid_passage_2","contextId":"u1_03_avoid_gap_third_ing","text":"Having slipped twice on the same corner, Anna now ____ that route and takes the longer path through the park. She says the extra five minutes are worth it.","answer":"avoids"}],"contextDependentParaphrases":[],"wrongParaphrases":["get closer to","look forward to","hold on to"],"misleadingDistractors":["join","encourage","permit"],"grammarForms":{"base":"avoid","thirdPerson":"avoids","past":"avoided","pastParticiple":"avoided","ing":"avoiding"},"grammarPatterns":["avoid + noun","avoid + -ing"]}]'::jsonb,'["avoidance","unavoidable"]'::jsonb,'[]'::jsonb,'live'),
('vocab_afford','afford','verb','to have enough money, time, or resources for something','[{"senseId":"afford_1","meaning":"to have enough money, time, or resources for something","acceptedParaphrases":["have enough money for","be able to pay for"],"masteryContexts":[{"contextId":"u1_04_afford_meaning","text":"The club had to cancel the trip because it could no longer afford the cost of the coach.","meaning":"have enough resources for a cost","wrongMeanings":["be willing to share a cost","agree to reduce the price of something","decide that a cost is unfair"]},{"contextId":"u1_04_afford_paraphrase","text":"My parents would love a bigger house, but they simply cannot afford one on a teacher’s salary.","meaning":"be financially able to pay","wrongMeanings":["be unwilling to spend money on something","feel sorry about the price of something","manage to borrow a large amount"]}],"situationDistractors":["Their family borrowed money to buy the expensive tennis equipment.","The club saved for three years before it could build a new pool.","The shop offered a discount on running shoes for students.","Our school decided not to buy new goalposts because the old ones were still safe.","The family spent a fortune on a new bicycle and then bought a second.","The shop closed early last weekend, because the manager wanted to watch the big football match.","The teacher cancelled swimming lessons because the pool flooded overnight.","Her coach praised the whole squad for its excellent teamwork."],"gapDistractors":[{"contextId":"u1_04_afford_gap_present_noun","answer":"afford","wrong":["advertise","describe","photograph"]},{"contextId":"u1_04_afford_gap_present_inf","answer":"afford","wrong":["pretend","threaten","deserve"]},{"contextId":"u1_04_afford_gap_past_noun","answer":"afford","wrong":["inspect","describe","photograph"]},{"contextId":"u1_04_afford_gap_past_inf","answer":"afford","wrong":["pretend","deserve","threaten"]},{"contextId":"u1_04_afford_gap_question_noun","answer":"afford","wrong":["advertise","describe","inspect"]},{"contextId":"u1_04_afford_gap_future_inf","answer":"afford","wrong":["pretend","forget","deserve"]}],"spellingErrors":["aford","affored","afforde","afferd","afoord","affoard"],"wordFamilyForms":[{"form":"afford","partOfSpeech":"verb","example":"Many families cannot afford to buy new football boots every year.","pedagogicallyUseful":true},{"form":"affordable","partOfSpeech":"adjective","example":"The club keeps its membership fees affordable for students.","pedagogicallyUseful":true,"altExample":"Second-hand equipment makes the sport affordable for beginners."},{"form":"unaffordable","partOfSpeech":"adjective","example":"For some families, private coaching is simply unaffordable.","pedagogicallyUseful":true,"altExample":"Tickets for the final were unaffordable for most of the students."}],"masteryPassages":[{"passageId":"u1_04_afford_passage_1","contextId":"u1_04_afford_gap_present_noun","text":"Tickets for the final cost more than most students could ____. In the end, the school paid for a small group to go.","answer":"afford"},{"passageId":"u1_04_afford_passage_2","contextId":"u1_04_afford_gap_present_inf","text":"For years, the club had trained in a cold hall because it could not ____ a better venue. This year a local company paid for the move.","answer":"afford"}],"contextDependentParaphrases":[],"wrongParaphrases":["calculate the cost of","suggest a price for","refuse to pay for"],"misleadingDistractors":["borrow","suggest","calculate"],"grammarForms":{"base":"afford","thirdPerson":"affords","past":"afforded","pastParticiple":"afforded","ing":"affording"},"grammarPatterns":["can/could afford + noun","can/could afford + to-infinitive"],"teacherNote":"Usually tests ability to pay for something; avoid treating it as a general synonym for buy."}]'::jsonb,'["affordable","unaffordable"]'::jsonb,'["afford the cost","cannot afford"]'::jsonb,'live'),
('vocab_deny','deny','verb','to say that something is not true','[{"senseId":"deny_1","meaning":"to say that something is not true","acceptedParaphrases":["say is not true","reject a claim"],"masteryContexts":[{"contextId":"u1_05_deny_meaning","text":"The company continues to deny any responsibility for the accident, despite the evidence.","meaning":"state that a claim is false","wrongMeanings":["agree to accept the cost of a problem","refuse to answer a direct question","promise to explain what went wrong"]},{"contextId":"u1_05_deny_paraphrase","text":"Both players deny breaking the rules, but the video clearly shows that they did.","meaning":"declare an accusation to be untrue","wrongMeanings":["admit that a mistake was made","argue that a rule is unfair","caution others about a possible foul"]}],"situationDistractors":["The athlete admitted that he had missed the test.","The player told the referee he was sorry for the foul.","The coach refused to answer any questions after the match.","Her club announced that the match would be played at the weekend.","The referee admitted his mistake and apologised to both teams afterwards.","At the end of the season, their head coach thanked everybody in the squad for their effort.","One referee explained the new offside rule to the captains before the match started today."],"gapDistractors":[{"contextId":"u1_05_deny_gap_base_ing","answer":"deny","wrong":["admit","regret","confess"]},{"contextId":"u1_05_deny_gap_third_ing","answer":"denies","wrong":["admits","confesses","regrets"]},{"contextId":"u1_05_deny_gap_past_that","answer":"denied","wrong":["photographed","inspected","borrowed"]},{"contextId":"u1_05_deny_gap_perfect_that","answer":"denied","wrong":["repaired","measured","borrowed"]},{"contextId":"u1_05_deny_gap_past_perfect_ing","answer":"denied","wrong":["hoped","planned","wanted"]}],"spellingErrors":["denie","deney","dany","denay","deni","denny"],"wordFamilyForms":[{"form":"deny","partOfSpeech":"verb","example":"The player continued to deny that he had broken the rules.","pedagogicallyUseful":true},{"form":"denial","partOfSpeech":"noun","example":"Despite his denial, the video showed him touching the ball.","pedagogicallyUseful":true,"altExample":"The coach’s denial surprised everyone because the evidence was so clear."},{"form":"undeniable","partOfSpeech":"adjective","example":"Her talent for running is undeniable.","pedagogicallyUseful":true,"altExample":"It is undeniable that regular exercise improves concentration in lessons."}],"masteryPassages":[{"passageId":"u1_05_deny_passage_1","contextId":"u1_05_deny_gap_base_ing","text":"The captain was asked whether he had broken the rule. He did not ____ it; instead, he apologised and promised it would not happen again.","answer":"deny"},{"passageId":"u1_05_deny_passage_2","contextId":"u1_05_deny_gap_third_ing","text":"Reporters kept asking whether the club would sign a new striker. The manager ____ every rumour, saying that nothing had been agreed.","answer":"denied"}],"contextDependentParaphrases":[],"wrongParaphrases":["say is probably true","promise to do it","feel sorry for it"],"misleadingDistractors":["admit","regret","promise"],"grammarForms":{"base":"deny","thirdPerson":"denies","past":"denied","pastParticiple":"denied","ing":"denying"},"grammarPatterns":["deny + -ing","deny + that-clause"],"teacherNote":"Use the say-something-is-not-true sense here; the refusal sense is separate."}]'::jsonb,'["denial","undeniable"]'::jsonb,'[]'::jsonb,'live'),
('vocab_permit','permit','verb','to allow something to happen','[{"senseId":"permit_1","meaning":"to allow something to happen","acceptedParaphrases":["allow","give permission for"],"masteryContexts":[{"contextId":"u1_06_permit_meaning","text":"Our flexible timetable will permit you to study at your own pace.","meaning":"let something go ahead without stopping it","wrongMeanings":["force someone to follow a plan","help someone to understand a topic","expect something to be finished quickly"]},{"contextId":"u1_06_permit_paraphrase","text":"The council will not permit anyone to build on the old playing field, because it is protected land.","meaning":"give official approval for something","wrongMeanings":["officially ask someone to leave a place","strongly advise against doing something","pay for work to be done"]}],"situationDistractors":["The rules forbid spectators from entering the training area.","The coach asked spectators politely to move away from the track.","The centre was closed for repairs during the holiday.","The referee warned the player about his behaviour."],"gapDistractors":[{"contextId":"u1_06_permit_gap_base_object","answer":"permit","wrong":["suggest","explain","announce"]},{"contextId":"u1_06_permit_gap_third_ing","answer":"permits","wrong":["hopes","plans","discourages"]},{"contextId":"u1_06_permit_gap_past_object","answer":"permitted","wrong":["suggested","explained","mentioned"]},{"contextId":"u1_06_permit_gap_passive_present","answer":"permitted","wrong":["explained","announced","described"]},{"contextId":"u1_06_permit_gap_passive_past","answer":"permitted","wrong":["suggested","mentioned","discussed"]}],"spellingErrors":["pemit","permet","permitt","premit","permmit","permiet"],"masteryPassages":[{"passageId":"u1_06_permit_passage_1","contextId":"u1_06_permit_gap_base_object","text":"The sign at the gate says that dogs are not welcome. The park rules do not ____ pets on the sports field, even on a lead.","answer":"permit"},{"passageId":"u1_06_permit_passage_2","contextId":"u1_06_permit_gap_third_ing","text":"Candidates must leave all bags outside the room. Phones are not ____ in the examination hall under any circumstances.","answer":"permitted"}],"contextDependentParaphrases":[],"wrongParaphrases":["stop","require","dislike"],"misleadingDistractors":["prevent","demand","resent"],"grammarForms":{"base":"permit","thirdPerson":"permits","past":"permitted","pastParticiple":"permitted","ing":"permitting"},"grammarPatterns":["permit + object + to-infinitive","permit + -ing","be permitted + to-infinitive"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_arrange','arrange','verb','to organise or make plans for something','[{"senseId":"arrange_1","meaning":"to organise or make plans for something","acceptedParaphrases":["organise","plan"],"masteryContexts":[{"contextId":"u1_07_arrange_meaning","text":"Please arrange a time that suits everyone so that we can all meet on Saturday.","meaning":"make plans for something in advance","wrongMeanings":["reschedule an important meeting again","check that people are available","remind people about a deadline"]},{"contextId":"u1_07_arrange_paraphrase","text":"My uncle has offered to arrange transport to the airport for the whole team.","meaning":"put necessary plans in place","wrongMeanings":["pay the cost of a journey","give directions to a place","suggest a route for the trip"]}],"situationDistractors":["Their coach cancelled the extra practice session at the last minute.","The players forgot where the bus was meeting them.","Our school hoped that the weather would stay dry for the final.","A volunteer cleaned the changing rooms before the tournament.","Their team arrived very late and the match started without them.","The coach forgot the match kit, so the players had to borrow shirts from the other team."],"gapDistractors":[{"contextId":"u1_07_arrange_gap_base_noun","answer":"arrange","wrong":["inspect","photograph","describe"]},{"contextId":"u1_07_arrange_gap_third_for","answer":"arranges","wrong":["inspects","photographs","describes"]},{"contextId":"u1_07_arrange_gap_past_noun","answer":"arranged","wrong":["inspected","photographed","repaired"]},{"contextId":"u1_07_arrange_gap_perfect_to","answer":"arranged","wrong":["inspected","photographed","described"]},{"contextId":"u1_07_arrange_gap_past_for","answer":"arranged","wrong":["inspects","photographs","describes"]}],"spellingErrors":["arange","arrenge","arrnage","arrage","arrang","arrangge"],"wordFamilyForms":[{"form":"arrange","partOfSpeech":"verb","example":"Could you arrange a meeting with the coach for Friday?","pedagogicallyUseful":true},{"form":"arrangement","partOfSpeech":"noun","example":"The new arrangement allows students to train before school.","pedagogicallyUseful":true,"altExample":"The travel arrangement saved the team two hours on the way home."},{"form":"rearrange","partOfSpeech":"verb","example":"We had to rearrange the match because of the storm.","pedagogicallyUseful":true,"altExample":"Could we rearrange the training session so that it starts after lunch?"}],"masteryPassages":[{"passageId":"u1_07_arrange_passage_1","contextId":"u1_07_arrange_gap_base_noun","text":"Our class wants to visit the science museum next month. Mr Okafor has offered to ____ a coach, and we must bring the money by Friday.","answer":"arrange"},{"passageId":"u1_07_arrange_passage_2","contextId":"u1_07_arrange_gap_third_for","text":"Everything was ready for the surprise party. Priya had ____ the food, the music and the decorations while her sister kept the guest of honour busy.","answer":"arranged"}],"contextDependentParaphrases":[],"wrongParaphrases":["cancel","postpone","observe"],"misleadingDistractors":["cancel","deny","estimate"],"grammarForms":{"base":"arrange","thirdPerson":"arranges","past":"arranged","pastParticiple":"arranged","ing":"arranging"},"grammarPatterns":["arrange + noun","arrange + to-infinitive","arrange for + object + to-infinitive"]}]'::jsonb,'["arrangement","rearrange"]'::jsonb,'[]'::jsonb,'live'),
('vocab_urge','urge','verb','to strongly encourage someone to do something','[{"senseId":"urge_1","meaning":"to strongly encourage someone to do something","acceptedParaphrases":["strongly encourage","press"],"masteryContexts":[{"contextId":"u1_08_urge_meaning","text":"Doctors strongly urge patients to take up gentle exercise because the benefits are so large, though the choice is always theirs.","meaning":"press someone hard to do something","wrongMeanings":["warn someone about a danger","politely ask someone to wait","enquire about how someone is feeling"]},{"contextId":"u1_08_urge_paraphrase","text":"Friends who live here urge new students to try the local food, which is cheap, delicious and unlike anything most newcomers have tasted.","meaning":"push someone firmly toward action","wrongMeanings":["quietly tell someone what to avoid","show someone how a dish is made","allow someone to make a choice"]}],"situationDistractors":["The coach allowed the players to choose whether to drink water.","Doctors forbid teenagers from taking part in any sport.","Her teacher quietly told the students the match times.","The captain ignored the doctor''s advice and played anyway.","The coach was far too busy that week to discuss anyone’s training.","After the final whistle, the captain warmly thanked the supporters who had travelled so far.","The headmaster refused every request to discuss the controversial timetable changes.","The stadium manager delayed opening the gates until security checks finished."],"gapDistractors":[{"contextId":"u1_08_urge_gap_base_active","answer":"urge","wrong":["suggest","explain","announce"]},{"contextId":"u1_08_urge_gap_third_active","answer":"urges","wrong":["suggests","explains","announces"]},{"contextId":"u1_08_urge_gap_past_active","answer":"urged","wrong":["suggested","explained","announced"]},{"contextId":"u1_08_urge_gap_perfect_active","answer":"urged","wrong":["suggested","explained","announced"]},{"contextId":"u1_08_urge_gap_passive_present","answer":"urged","wrong":["described","mentioned","discussed"]},{"contextId":"u1_08_urge_gap_passive_past","answer":"urged","wrong":["described","mentioned","discussed"]}],"spellingErrors":["urdge","uerge","urege","urgue","urgge","ugre"],"masteryPassages":[{"passageId":"u1_08_urge_passage_1","contextId":"u1_08_urge_gap_base_active","text":"The health minister appeared on television. She will ____ every adult to exercise for thirty minutes a day, because the figures on heart disease are so worrying.","answer":"urge"},{"passageId":"u1_08_urge_passage_2","contextId":"u1_08_urge_gap_third_active","text":"At half-time the captain gathered the team. \"Don’t give up now,\" she ____ them, and the players ran back onto the pitch with fresh energy.","answer":"urged"}],"contextDependentParaphrases":[],"wrongParaphrases":["gently refuse","carefully check","quickly forget"],"misleadingDistractors":["forbid","ignore","estimate"],"grammarForms":{"base":"urge","thirdPerson":"urges","past":"urged","pastParticiple":"urged","ing":"urging"},"grammarPatterns":["urge + object + to-infinitive","be urged + to-infinitive"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_recommend','recommend','verb','to suggest something as suitable or useful','[{"senseId":"recommend_1","meaning":"to suggest something as suitable or useful","acceptedParaphrases":["suggest","advise"],"masteryContexts":[{"contextId":"u1_09_recommend_meaning","text":"My dentist has just retired, so I am asking my colleagues to recommend someone they have been happy with.","meaning":"present something as a suitable choice","wrongMeanings":["offer something as a reward to a friend","give someone a reason to be pleased","warn someone about a poor choice"]},{"contextId":"u1_09_recommend_paraphrase","text":"I would highly recommend the new science museum; my whole class thought it was brilliant.","meaning":"advise choosing a particular option","wrongMeanings":["advise avoiding a particular place","describe the cost of a visit","invite someone to a special event"]}],"situationDistractors":["His coach ordered every player to wear a helmet.","The trainer warned players never to stretch before exercise.","She read a book about the history of cycling.","The shop refused to sell the shoes to children."],"gapDistractors":[{"contextId":"u1_09_recommend_gap_base_noun","answer":"recommend","wrong":["belong","depend","wait"]},{"contextId":"u1_09_recommend_gap_third_ing","answer":"recommends","wrong":["hopes","plans","wants"]},{"contextId":"u1_09_recommend_gap_past_noun","answer":"recommended","wrong":["belonged","depended","waited"]},{"contextId":"u1_09_recommend_gap_perfect_ing","answer":"recommended","wrong":["hoped","planned","wanted"]},{"contextId":"u1_09_recommend_gap_third_that","answer":"recommends","wrong":["photographs","inspects","repairs"]},{"contextId":"u1_09_recommend_gap_past_that","answer":"recommended","wrong":["photographed","inspected","repaired"]}],"spellingErrors":["recomend","reccomend","recommed","recomand","recommand","reccommend"],"wordFamilyForms":[{"form":"recommend","partOfSpeech":"verb","example":"My coach would recommend this book to any young runner.","pedagogicallyUseful":true},{"form":"recommendation","partOfSpeech":"noun","example":"On my teacher’s recommendation, I joined the swimming club.","pedagogicallyUseful":true,"altExample":"On the coach’s recommendation, the club bought lighter running shoes."},{"form":"recommended","partOfSpeech":"adjective","example":"The recommended amount of exercise for teenagers is one hour a day.","pedagogicallyUseful":true,"altExample":"This stretching routine is recommended for anyone who sits all day.","note":"Participial adjective."}],"masteryPassages":[{"passageId":"u1_09_recommend_passage_1","contextId":"u1_09_recommend_gap_base_noun","text":"I have just read an excellent novel about a young runner. I would strongly ____ it to anyone who enjoys stories about sport.","answer":"recommend"},{"passageId":"u1_09_recommend_passage_2","contextId":"u1_09_recommend_gap_third_ing","text":"My ankle was still swollen after the match. My doctor ____ that I rest it for two weeks before I start training again.","answer":"recommended"}],"contextDependentParaphrases":[],"wrongParaphrases":["refuse","borrow","imagine"],"misleadingDistractors":["forbid","demand","deny"],"grammarForms":{"base":"recommend","thirdPerson":"recommends","past":"recommended","pastParticiple":"recommended","ing":"recommending"},"grammarPatterns":["recommend + -ing","recommend + noun + to + person","recommend + that-clause"]}]'::jsonb,'["recommendation","recommended"]'::jsonb,'["strongly recommend","recommend doing"]'::jsonb,'live'),
('vocab_demand','demand','verb','to require a lot of effort, skill, attention, or resources','[{"senseId":"demand_1","meaning":"to require a lot of effort, skill, attention, or resources","acceptedParaphrases":["require","need"],"masteryContexts":[{"contextId":"u1_10_demand_meaning","text":"Marathon training can demand patience, discipline and a great deal of time.","meaning":"require considerable effort or attention","wrongMeanings":["offer a great deal of enjoyment","provide detailed advice to nervous beginners","allow plenty of time for rest"]},{"contextId":"u1_10_demand_paraphrase","text":"Learning two languages at once will demand a lot of concentration.","meaning":"place heavy requirements on something","wrongMeanings":["make a difficult task seem simpler","offer someone a reward for working hard","request that a task is delayed"]}],"situationDistractors":["The sport needs only one hour of practice a month.","Their coach offered the players a day off.","The team celebrated after the match with a long meal.","Playing in the park costs nothing and takes very little time.","The new gym offers inexpensive membership to students who want to stay healthy.","Once the training session had finished, several parents carried the heavy equipment to the minibus.","After the long weekend, the club chairman thanked every volunteer for painting the changing rooms.","Their captain shook hands with each player before leaving.","Supervisors inspected the equipment cupboards immediately afterwards.","Volunteers repainted the changing rooms during the holidays.","The head teacher congratulated everybody warmly after the summer sports ceremony ended."],"gapDistractors":[{"contextId":"u1_10_demand_gap_base_noun","answer":"demand","wrong":["excuse","replace","shorten"]},{"contextId":"u1_10_demand_gap_third_noun","answer":"demands","wrong":["prevents","replaces","excuses"]},{"contextId":"u1_10_demand_gap_past_noun","answer":"demanded","wrong":["prevented","replaced","excused"]},{"contextId":"u1_10_demand_gap_perfect_noun","answer":"demanded","wrong":["prevented","replaced","excused"]},{"contextId":"u1_10_demand_gap_past_that","answer":"demanded","wrong":["photographed","inspected","repaired"]},{"contextId":"u1_10_demand_gap_third_that","answer":"demands","wrong":["photographs","inspects","repairs"]}],"spellingErrors":["demend","damand","demmand","deamnd","demant","demund"],"masteryPassages":[{"passageId":"u1_10_demand_passage_1","contextId":"u1_10_demand_gap_base_noun","text":"Being a professional musician is not easy. The job can ____ years of practice, long journeys and very little sleep before a big concert.","answer":"demand"},{"passageId":"u1_10_demand_passage_2","contextId":"u1_10_demand_gap_third_noun","text":"The workers were angry about their pay. They ____ a meeting with the manager and refused to return to work until they had spoken to her.","answer":"demanded"}],"contextDependentParaphrases":[],"wrongParaphrases":["refuse","offer","borrow"],"misleadingDistractors":["avoid","permit","relax"],"grammarForms":{"base":"demand","thirdPerson":"demands","past":"demanded","pastParticiple":"demanded","ing":"demanding"},"grammarPatterns":["demand + noun","demand + that-clause"]}]'::jsonb,'[]'::jsonb,'["demand time","physically demanding"]'::jsonb,'live')
