('language-bank:opponent_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Chess players must think about the next move that their ____ is likely to make.","acceptedAnswers":["opponent"],"distractors":[{"text":"coach","reason":"Fits grammatically, but a coach advises from outside the game and does not make moves."},{"text":"judge","reason":"Fits grammatically, but a judge scores or rules on a game and does not make moves in it."},{"text":"referee","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."}],"linkedVocabularyIds":["vocab_opponent"],"primaryEvidenceTargetId":"vocab_opponent","languageBankContextId":"opponent_ctx_4"}'::jsonb,'live'),
