('language-bank:opponent_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"When two teams meet, each team is the other’s ____, but off the pitch the players are often friends.","acceptedAnswers":["opponent"],"distractors":[{"text":"supporter","reason":"Fits grammatically, but a supporter would be on the team’s side, which contradicts two teams meeting to compete."},{"text":"partner","reason":"Fits grammatically, but a partner is on the same side, which contradicts two teams meeting to compete."},{"text":"manager","reason":"Fits grammatically, but a manager belongs to the team, not the other side."}],"linkedVocabularyIds":["vocab_opponent"],"primaryEvidenceTargetId":"vocab_opponent","languageBankContextId":"opponent_ctx_6"}'::jsonb,'live'),
