('language-bank:tournament_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"He scored the winning goal in the semi-final of the ____, which his team went on to win.","acceptedAnswers":["tournament"],"distractors":[{"text":"season","reason":"Fits grammatically, but a season is a period of time, and a semi-final belongs to one event."},{"text":"camp","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"exhibition","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."}],"linkedVocabularyIds":["vocab_tournament"],"primaryEvidenceTargetId":"vocab_tournament","languageBankContextId":"tournament_ctx_2"}'::jsonb,'live'),
