('language-bank:goal-oriented_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The manager is ____: she cares less about how a task is done than about reaching the agreed result by Friday.","acceptedAnswers":["goal-oriented"],"distractors":[{"text":"detail-oriented","reason":"Fits grammatically, but detail-oriented means paying attention to small points, which contradicts caring less about how a task is done."},{"text":"team-oriented","reason":"Fits grammatically, but team-oriented means focused on the group, but the sentence is about reaching an agreed result."},{"text":"process-oriented","reason":"Fits grammatically, but process-oriented means focused on how a task is done, which is the opposite of the sentence."}],"linkedVocabularyIds":["vocab_goal_oriented"],"primaryEvidenceTargetId":"vocab_goal_oriented","languageBankContextId":"goal-oriented_ctx_1"}'::jsonb,'live'),
('language-bank:goal-oriented_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"A ____ runner writes a target time for each race and trains only in ways that will help reach it.","acceptedAnswers":["goal-oriented"],"distractors":[{"text":"detail-oriented","reason":"Fits grammatically, but detail-oriented means paying attention to small points, but the sentence is about aiming for a target time."},{"text":"team-oriented","reason":"Fits grammatically, but team-oriented means focused on the group, but the sentence is about one runner’s target time."},{"text":"health-conscious","reason":"Fits grammatically, but health-conscious means caring about health, but the sentence is about reaching a target time."}],"linkedVocabularyIds":["vocab_goal_oriented"],"primaryEvidenceTargetId":"vocab_goal_oriented","languageBankContextId":"goal-oriented_ctx_2"}'::jsonb,'live'),
('language-bank:goal-oriented_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Because she is so ____, she checks every month whether she is closer to the grades she has set herself.","acceptedAnswers":["goal-oriented"],"distractors":[{"text":"team-oriented","reason":"Fits grammatically, but team-oriented means focused on the group, but the sentence is about her own targets."},{"text":"people-oriented","reason":"Fits grammatically, but people-oriented means focused on other people, but the sentence is about her own targets."},{"text":"family-oriented","reason":"Fits grammatically, but family-oriented means focused on family life, but the sentence is about her own targets."}],"linkedVocabularyIds":["vocab_goal_oriented"],"primaryEvidenceTargetId":"vocab_goal_oriented","languageBankContextId":"goal-oriented_ctx_3"}'::jsonb,'live'),
('language-bank:goal-oriented_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The coach wanted ____ players, who would keep their eyes on the final aim of promotion rather than on how enjoyable each session was.","acceptedAnswers":["goal-oriented"],"distractors":[{"text":"fun-loving","reason":"Fits grammatically, but fun-loving means enjoying having fun, which is the opposite of keeping eyes on the final aim."},{"text":"easy-going","reason":"Fits grammatically, but easy-going means relaxed, which does not fit keeping eyes on the final aim."},{"text":"sociable","reason":"Fits grammatically, but sociable means enjoying other people’s company, which does not describe focus on the final aim."}],"linkedVocabularyIds":["vocab_goal_oriented"],"primaryEvidenceTargetId":"vocab_goal_oriented","languageBankContextId":"goal-oriented_ctx_4"}'::jsonb,'live'),
('language-bank:goal-oriented_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Our school is increasingly ____: every department sets yearly targets and reports on whether it has reached them.","acceptedAnswers":["goal-oriented"],"distractors":[{"text":"customer-oriented","reason":"Fits grammatically, but customer-oriented means focused on serving customers, but the sentence is about setting targets and reporting results."},{"text":"family-oriented","reason":"Fits grammatically, but family-oriented means focused on family life, but the sentence is about setting targets and reporting results."},{"text":"safety-oriented","reason":"Fits grammatically, but safety-oriented means focused on preventing harm, but the sentence is about setting targets and reporting results."}],"linkedVocabularyIds":["vocab_goal_oriented"],"primaryEvidenceTargetId":"vocab_goal_oriented","languageBankContextId":"goal-oriented_ctx_5"}'::jsonb,'live'),
('language-bank:goal-oriented_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"He was never ____: he drifted from one hobby to another without ever deciding what he wanted to achieve.","acceptedAnswers":["goal-oriented"],"distractors":[{"text":"team-oriented","reason":"Fits grammatically, but team-oriented means focused on the group, but the sentence is about not deciding what he wanted to achieve."},{"text":"detail-oriented","reason":"Fits grammatically, but detail-oriented means paying attention to small points, but the sentence is about not deciding what he wanted to achieve."},{"text":"safety-oriented","reason":"Fits grammatically, but safety-oriented means focused on preventing harm, but the sentence is about not deciding what he wanted to achieve."}],"linkedVocabularyIds":["vocab_goal_oriented"],"primaryEvidenceTargetId":"vocab_goal_oriented","languageBankContextId":"goal-oriented_ctx_6"}'::jsonb,'live'),
('language-bank:achievement_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Finishing the marathon in under four hours was a major ____ for someone who had only started running a year ago.","acceptedAnswers":["achievement"],"distractors":[{"text":"disappointment","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"embarrassment","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"mistake","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."}],"linkedVocabularyIds":["vocab_achievement"],"primaryEvidenceTargetId":"vocab_achievement","languageBankContextId":"achievement_ctx_1"}'::jsonb,'live'),
('language-bank:achievement_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The coach called her place on the national team the most difficult ____ of her career, because no one from the school had ever done it before.","acceptedAnswers":["achievement"],"distractors":[{"text":"defeat","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"injury","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"loss","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."}],"linkedVocabularyIds":["vocab_achievement"],"primaryEvidenceTargetId":"vocab_achievement","languageBankContextId":"achievement_ctx_2"}'::jsonb,'live'),
('language-bank:achievement_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The school celebrated the ____ of its students, who had won three national prizes in a single year.","acceptedAnswers":["achievement"],"distractors":[{"text":"mistake","reason":"Fits grammatically, but a mistake is an error, which does not fit celebrated and prizes."},{"text":"absence","reason":"Fits grammatically, but an absence is not being present, which does not fit celebrated and prizes."},{"text":"expectation","reason":"Fits grammatically, but an expectation is what people think will happen, but the school celebrated what the students had actually done."}],"linkedVocabularyIds":["vocab_achievement"],"primaryEvidenceTargetId":"vocab_achievement","languageBankContextId":"achievement_ctx_3"}'::jsonb,'live'),
('language-bank:achievement_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Her proudest ____ was teaching herself to swim at the age of forty.","acceptedAnswers":["achievement"],"distractors":[{"text":"mistake","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"regret","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"disappointment","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."}],"linkedVocabularyIds":["vocab_achievement"],"primaryEvidenceTargetId":"vocab_achievement","languageBankContextId":"achievement_ctx_4"}'::jsonb,'live'),
('language-bank:achievement_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"It was a great ____ for such a small club to reach the national final against much richer teams.","acceptedAnswers":["achievement"],"distractors":[{"text":"mistake","reason":"Fits grammatically, but a mistake contradicts great and reach the final."},{"text":"accident","reason":"Fits grammatically, but an accident is something unplanned and harmful, but the club earned its place in the final."},{"text":"embarrassment","reason":"Fits grammatically, but an embarrassment would be shameful, but reaching the final against richer teams is something to be proud of."}],"linkedVocabularyIds":["vocab_achievement"],"primaryEvidenceTargetId":"vocab_achievement","languageBankContextId":"achievement_ctx_5"}'::jsonb,'live'),
('language-bank:achievement_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Passing every exam with top grades was an ____ that his whole family was proud of.","acceptedAnswers":["achievement"],"distractors":[{"text":"accident","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"error","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"obstacle","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."}],"linkedVocabularyIds":["vocab_achievement"],"primaryEvidenceTargetId":"vocab_achievement","languageBankContextId":"achievement_ctx_6"}'::jsonb,'live'),
('language-bank:elite_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The ____ squad is closed to all but the top one per cent of players in the country, chosen purely on results.","acceptedAnswers":["elite"],"distractors":[{"text":"open","reason":"Fits grammatically, but an open squad lets anyone join, but closed to all but the top one per cent says entry is limited."},{"text":"social","reason":"Fits grammatically, but a social squad plays for fun, but closed to all but the top one per cent and chosen purely on results says it is for the best."},{"text":"beginner","reason":"Fits grammatically, but a beginner squad is for new players, who cannot be among the top one per cent in the country."}],"linkedVocabularyIds":["vocab_elite"],"primaryEvidenceTargetId":"vocab_elite","languageBankContextId":"elite_ctx_1"}'::jsonb,'live'),
('language-bank:elite_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Entry to the ____ competition is restricted to the top ten ranked players in the country, so most club players never qualify.","acceptedAnswers":["elite"],"distractors":[{"text":"open","reason":"Fits grammatically, but an open competition lets anyone enter, but restricted to the top ten ranked players says entry is limited."},{"text":"social","reason":"Fits grammatically, but a social competition is for fun, but restricted to the top ten ranked players says it is for the best."},{"text":"recreational","reason":"Fits grammatically, but a recreational competition is for enjoyment, but restricted to the top ten ranked players says it is for the best."}],"linkedVocabularyIds":["vocab_elite"],"primaryEvidenceTargetId":"vocab_elite","languageBankContextId":"elite_ctx_2"}'::jsonb,'live'),
('language-bank:elite_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Her coach said she had the ability to reach ____ level, which means competing against the best in the world.","acceptedAnswers":["elite"],"distractors":[{"text":"club","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"amateur","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"social","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."}],"linkedVocabularyIds":["vocab_elite"],"primaryEvidenceTargetId":"vocab_elite","languageBankContextId":"elite_ctx_3"}'::jsonb,'live'),
('language-bank:elite_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Scholarships are offered only to ____ sports people, meaning those who rank in the top one per cent nationally.","acceptedAnswers":["elite"],"distractors":[{"text":"average","reason":"Fits grammatically, but average sports people are in the middle of the range, but meaning those who rank in the top one per cent says the opposite."},{"text":"casual","reason":"Fits grammatically, but casual sports people play for fun, but meaning those who rank in the top one per cent says the opposite."},{"text":"ordinary","reason":"Fits grammatically, but ordinary sports people are not exceptional, but meaning those who rank in the top one per cent says the opposite."}],"linkedVocabularyIds":["vocab_elite"],"primaryEvidenceTargetId":"vocab_elite","languageBankContextId":"elite_ctx_4"}'::jsonb,'live'),
('language-bank:elite_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Although he trains hard, he is still not good enough for the ____ squad, which only takes the very best players in the country.","acceptedAnswers":["elite"],"distractors":[{"text":"open","reason":"Fits grammatically, but an open squad takes anyone, but which only takes the very best players says the opposite."},{"text":"social","reason":"Fits grammatically, but a social squad plays for fun, but which only takes the very best players says the opposite."},{"text":"community","reason":"Fits grammatically, but a community squad is based on a local group, but which only takes the very best players in the country says the opposite."}],"linkedVocabularyIds":["vocab_elite"],"primaryEvidenceTargetId":"vocab_elite","languageBankContextId":"elite_ctx_5"}'::jsonb,'live'),
('language-bank:elite_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Scouts say the ____ footballers they saw at the new academy are among the best fifty players of their age in the whole country.","acceptedAnswers":["elite"],"distractors":[{"text":"average","reason":"Fits grammatically, but average footballers are in the middle of the range, but among the best fifty in the whole country says the opposite."},{"text":"ordinary","reason":"Fits grammatically, but ordinary footballers are not exceptional, but among the best fifty in the whole country says the opposite."},{"text":"typical","reason":"Fits grammatically, but typical footballers are like most others, but among the best fifty in the whole country says the opposite."}],"linkedVocabularyIds":["vocab_elite"],"primaryEvidenceTargetId":"vocab_elite","languageBankContextId":"elite_ctx_6"}'::jsonb,'live'),
('language-bank:overwhelming_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The support from the home crowd was so ____ that the young players could hardly think or hear their coach.","acceptedAnswers":["overwhelming"],"distractors":[{"text":"half-hearted","reason":"Fits grammatically, but half-hearted support lacks energy, which contradicts the players hardly being able to think or hear their coach."},{"text":"gentle","reason":"Fits grammatically, but gentle support is soft and quiet, which contradicts the players hardly being able to think or hear their coach."},{"text":"unobtrusive","reason":"Fits grammatically, but unobtrusive support is quiet and easy to ignore, which contradicts the players hardly being able to think or hear their coach."}],"linkedVocabularyIds":["vocab_overwhelming"],"primaryEvidenceTargetId":"vocab_overwhelming","languageBankContextId":"overwhelming_ctx_1"}'::jsonb,'live'),
('language-bank:overwhelming_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Voters gave the new mayor an ____ majority, with more than ninety per cent supporting her.","acceptedAnswers":["overwhelming"],"distractors":[{"text":"insignificant","reason":"Fits grammatically, but an insignificant majority is tiny, but more than ninety per cent supporting her shows a huge one."},{"text":"unconvincing","reason":"Fits grammatically, but an unconvincing majority is too small to persuade, but more than ninety per cent supporting her shows a huge one."},{"text":"inadequate","reason":"Fits grammatically, but an inadequate majority is too small, but more than ninety per cent supporting her shows a huge one."}],"linkedVocabularyIds":["vocab_overwhelming"],"primaryEvidenceTargetId":"vocab_overwhelming","languageBankContextId":"overwhelming_ctx_2"}'::jsonb,'live'),
('language-bank:overwhelming_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"After weeks of training, he felt an ____ sense of relief when the race was over, so strong that he cried at the finish line.","acceptedAnswers":["overwhelming"],"distractors":[{"text":"ordinary","reason":"Fits grammatically, but an ordinary sense of relief is not unusually strong, which contradicts so strong that he cried."},{"text":"unnoticeable","reason":"Fits grammatically, but an unnoticeable sense of relief is too slight to be noticed, which contradicts so strong that he cried."},{"text":"understated","reason":"Fits grammatically, but an understated sense of relief is kept low-key, which contradicts so strong that he cried."}],"linkedVocabularyIds":["vocab_overwhelming"],"primaryEvidenceTargetId":"vocab_overwhelming","languageBankContextId":"overwhelming_ctx_3"}'::jsonb,'live'),
('language-bank:overwhelming_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"There was ____ evidence that the player had broken the rules: the video, the witnesses and his own messages all agreed, and the committee had no doubt.","acceptedAnswers":["overwhelming"],"distractors":[{"text":"inconclusive","reason":"Fits grammatically, but inconclusive evidence leaves the matter in doubt, which contradicts the committee had no doubt."},{"text":"conflicting","reason":"Fits grammatically, but conflicting evidence disagrees with itself, which contradicts the video, witnesses and messages all agreed."},{"text":"insufficient","reason":"Fits grammatically, but insufficient evidence is not enough to decide, which contradicts the committee had no doubt."}],"linkedVocabularyIds":["vocab_overwhelming"],"primaryEvidenceTargetId":"vocab_overwhelming","languageBankContextId":"overwhelming_ctx_4"}'::jsonb,'live'),
('language-bank:overwhelming_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The amount of homework this week has been ____: it was so much that many students stopped trying to finish it all.","acceptedAnswers":["overwhelming"],"distractors":[{"text":"manageable","reason":"Fits grammatically, but manageable means possible to cope with, but so much that many students stopped trying says the opposite."},{"text":"reasonable","reason":"Fits grammatically, but reasonable means fair, but so much that many students stopped trying says the opposite."},{"text":"unremarkable","reason":"Fits grammatically, but unremarkable means nothing special, but so much that many students stopped trying shows it was extreme."}],"linkedVocabularyIds":["vocab_overwhelming"],"primaryEvidenceTargetId":"vocab_overwhelming","languageBankContextId":"overwhelming_ctx_5"}'::jsonb,'live'),
('language-bank:overwhelming_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"An ____ response from fans, with so many messages that the staff could not read or answer them all, surprised the club.","acceptedAnswers":["overwhelming"],"distractors":[{"text":"underwhelming","reason":"Fits grammatically, but an underwhelming response is a disappointing one, which contradicts so many messages that the staff could not answer them all."},{"text":"insufficient","reason":"Fits grammatically, but an insufficient response is not enough, which contradicts so many messages that the staff could not answer them all."},{"text":"unenthusiastic","reason":"Fits grammatically, but an unenthusiastic response shows little interest, which contradicts so many messages that the staff could not answer them all."}],"linkedVocabularyIds":["vocab_overwhelming"],"primaryEvidenceTargetId":"vocab_overwhelming","languageBankContextId":"overwhelming_ctx_6"}'::jsonb,'live'),
('language-bank:generation_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"People born in the nineties are often described as part of the same ____, because they grew up with similar technology.","acceptedAnswers":["generation"],"distractors":[{"text":"family","reason":"Fits grammatically, but a family is made up of relatives, not people born in the same period."},{"text":"neighbourhood","reason":"Fits grammatically, but a neighbourhood is a place where people live, not a group defined by when they were born."},{"text":"school","reason":"Fits grammatically, but a school is a place of education, not a group defined by when they were born."}],"linkedVocabularyIds":["vocab_generation"],"primaryEvidenceTargetId":"vocab_generation","languageBankContextId":"generation_ctx_1"}'::jsonb,'live'),
('language-bank:generation_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"A new ____ of players, all born after the year 2005, is replacing the champions who dominated the sport for years.","acceptedAnswers":["generation"],"distractors":[{"text":"season","reason":"Fits grammatically, but a season is part of the year, not a group of players born after 2005."},{"text":"century","reason":"Fits grammatically, but a century is one hundred years, not a group of players born after 2005."},{"text":"month","reason":"Fits grammatically, but a month is a period of about thirty days, not a group of players born after 2005."}],"linkedVocabularyIds":["vocab_generation"],"primaryEvidenceTargetId":"vocab_generation","languageBankContextId":"generation_ctx_2"}'::jsonb,'live'),
('language-bank:generation_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Each ____ of people, born within a few years of each other, grows up with different music, technology and ideas about work.","acceptedAnswers":["generation"],"distractors":[{"text":"family","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"community","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"neighbourhood","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."}],"linkedVocabularyIds":["vocab_generation"],"primaryEvidenceTargetId":"vocab_generation","languageBankContextId":"generation_ctx_3"}'::jsonb,'live'),
