('language-bank:challenge_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Playing the champions away from home will be a serious ____ for our young team, but we are ready to try.","acceptedAnswers":["challenge"],"distractors":[{"text":"advantage","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"relief","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"bonus","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."}],"linkedVocabularyIds":["vocab_challenge"],"primaryEvidenceTargetId":"vocab_challenge","languageBankContextId":"challenge_ctx_2"}'::jsonb,'live'),
('language-bank:challenge_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Adults learning an instrument face a real ____ in staying patient when progress feels slow.","acceptedAnswers":["challenge"],"distractors":[{"text":"hobby","reason":"Fits grammatically, but a hobby is an activity chosen for pleasure, not a difficulty that adults face."},{"text":"habit","reason":"Fits grammatically, but a habit is something done regularly, not a difficulty that adults face."},{"text":"privilege","reason":"Fits grammatically, but a privilege is a special advantage, not a difficulty that adults face."}],"linkedVocabularyIds":["vocab_challenge"],"primaryEvidenceTargetId":"vocab_challenge","languageBankContextId":"challenge_ctx_3"}'::jsonb,'live'),
