('language-bank:challenge_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Finding enough time for training while studying full-time is the biggest ____ for most athletes at university.","acceptedAnswers":["challenge"],"distractors":[{"text":"advantage","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"benefit","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"reward","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."}],"linkedVocabularyIds":["vocab_challenge"],"primaryEvidenceTargetId":"vocab_challenge","languageBankContextId":"challenge_ctx_5"}'::jsonb,'live'),
