('language-bank:solution_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"One practical ____ to the noise problem is to move the matches to the afternoon.","acceptedAnswers":["solution"],"distractors":[{"text":"obstacle","reason":"Fits grammatically, but an obstacle makes a problem harder, but to move the matches describes a way of ending the noise."},{"text":"threat","reason":"Fits grammatically, but a threat is a danger, but to move the matches describes a way of ending the noise."},{"text":"cause","reason":"Fits grammatically, but a cause is what creates a problem, but to move the matches describes a way of ending the noise."}],"linkedVocabularyIds":["vocab_solution"],"primaryEvidenceTargetId":"vocab_solution","languageBankContextId":"solution_ctx_2"}'::jsonb,'live'),
('language-bank:solution_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"There is no simple ____ to the problem of injuries among young athletes, but good coaching helps.","acceptedAnswers":["solution"],"distractors":[{"text":"definition","reason":"Fits grammatically, but a definition says what a word means, but good coaching helps describes a way of reducing the problem."},{"text":"prediction","reason":"Fits grammatically, but a prediction says what will happen, but good coaching helps describes a way of reducing the problem."},{"text":"excuse","reason":"Fits grammatically, but an excuse defends a failure, but good coaching helps describes a way of reducing the problem."}],"linkedVocabularyIds":["vocab_solution"],"primaryEvidenceTargetId":"vocab_solution","languageBankContextId":"solution_ctx_3"}'::jsonb,'live'),
('language-bank:solution_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The mechanic said there was no easy ____ to the engine fault: the whole part would have to be replaced.","acceptedAnswers":["solution"],"distractors":[{"text":"objection","reason":"Fits grammatically, but an objection is a complaint, but the whole part would have to be replaced describes a way of dealing with the fault."},{"text":"warning","reason":"Fits grammatically, but a warning tells people about danger, but the whole part would have to be replaced describes a way of dealing with the fault."},{"text":"threat","reason":"Fits grammatically, but a threat is a danger, but the whole part would have to be replaced describes a way of dealing with the fault."}],"linkedVocabularyIds":["vocab_solution"],"primaryEvidenceTargetId":"vocab_solution","languageBankContextId":"solution_ctx_4"}'::jsonb,'live'),
('language-bank:solution_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The puzzle was finally finished when the students found the ____ that explained all of the clues.","acceptedAnswers":["solution"],"distractors":[{"text":"hint","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"penalty","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"question","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."}],"linkedVocabularyIds":["vocab_solution"],"primaryEvidenceTargetId":"vocab_solution","languageBankContextId":"solution_ctx_5"}'::jsonb,'live'),
('language-bank:solution_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Sharing equipment turned out to be a cheap ____ to the club''s money problem, since no new balls had to be bought.","acceptedAnswers":["solution"],"distractors":[{"text":"penalty","reason":"Fits grammatically, but a penalty is a punishment, which does not describe a way of ending a money problem."},{"text":"symptom","reason":"Fits grammatically, but a symptom is a sign of a problem, not a way of ending it."},{"text":"nuisance","reason":"Fits grammatically, but a nuisance is an annoyance, which does not describe a way of ending a money problem."}],"linkedVocabularyIds":["vocab_solution"],"primaryEvidenceTargetId":"vocab_solution","languageBankContextId":"solution_ctx_6"}'::jsonb,'live'),
('language-bank:pastime_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Collecting old coins is a popular ____ among retired people, who enjoy it in the afternoons.","acceptedAnswers":["pastime"],"distractors":[{"text":"profession","reason":"Fits grammatically, but a profession is a job, but who enjoy it in the afternoons describes something done for pleasure."},{"text":"duty","reason":"Fits grammatically, but a duty is something you must do, but who enjoy it describes something done for pleasure."},{"text":"sport","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."}],"linkedVocabularyIds":["vocab_pastime"],"primaryEvidenceTargetId":"vocab_pastime","languageBankContextId":"pastime_ctx_1"}'::jsonb,'live'),
('language-bank:pastime_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"For many teenagers, playing video games is a favourite ____, not a way of earning money.","acceptedAnswers":["pastime"],"distractors":[{"text":"job","reason":"Fits grammatically, but a job is work done for money, which the sentence rules out with not a way of earning money."},{"text":"subject","reason":"Fits grammatically, but a subject is something studied at school, not something done for enjoyment."},{"text":"lesson","reason":"Fits grammatically, but a lesson is a period of teaching, not something done for enjoyment."}],"linkedVocabularyIds":["vocab_pastime"],"primaryEvidenceTargetId":"vocab_pastime","languageBankContextId":"pastime_ctx_2"}'::jsonb,'live'),
('language-bank:pastime_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Cricket began as a village ____, played on summer evenings for fun, before it became a professional sport.","acceptedAnswers":["pastime"],"distractors":[{"text":"business","reason":"Fits grammatically, but a business is run to earn money, but played on summer evenings for fun describes an activity enjoyed."},{"text":"duty","reason":"Fits grammatically, but a duty is something you must do, but for fun describes an activity enjoyed."},{"text":"profession","reason":"Fits grammatically, but a profession is a job, but for fun and before it became a professional sport rule it out."}],"linkedVocabularyIds":["vocab_pastime"],"primaryEvidenceTargetId":"vocab_pastime","languageBankContextId":"pastime_ctx_3"}'::jsonb,'live'),
('language-bank:pastime_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Her favourite ____ is walking in the hills on Sunday mornings, when she has no homework.","acceptedAnswers":["pastime"],"distractors":[{"text":"subject","reason":"Fits grammatically, but a subject is something studied at school, but she has no homework shows this is free-time enjoyment."},{"text":"lesson","reason":"Fits grammatically, but a lesson is a period of teaching, but she has no homework shows this is free-time enjoyment."},{"text":"task","reason":"Fits grammatically, but a task is a piece of work, but she has no homework shows this is free-time enjoyment."}],"linkedVocabularyIds":["vocab_pastime"],"primaryEvidenceTargetId":"vocab_pastime","languageBankContextId":"pastime_ctx_4"}'::jsonb,'live'),
('language-bank:pastime_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Not everyone sees fishing as an exciting ____, but millions of people enjoy it as a relaxing activity every week.","acceptedAnswers":["pastime"],"distractors":[{"text":"subject","reason":"Fits grammatically, but a subject is something studied at school, but millions of people enjoy it as a relaxing activity."},{"text":"lesson","reason":"Fits grammatically, but a lesson is a period of teaching, but millions of people enjoy it as a relaxing activity."},{"text":"season","reason":"Fits grammatically, but a season is part of the year, not an activity people do every week."}],"linkedVocabularyIds":["vocab_pastime"],"primaryEvidenceTargetId":"vocab_pastime","languageBankContextId":"pastime_ctx_5"}'::jsonb,'live'),
('language-bank:pastime_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Many parents want their children to find a ____ for their free time that is not connected to screens, such as painting or gardening.","acceptedAnswers":["pastime"],"distractors":[{"text":"career","reason":"Fits grammatically, but a career is a long-term job, but for their free time says the activity is for enjoyment."},{"text":"subject","reason":"Fits grammatically, but a subject is studied at school, but for their free time says the activity is for enjoyment."},{"text":"profession","reason":"Fits grammatically, but a profession is a job, but for their free time says the activity is for enjoyment."}],"linkedVocabularyIds":["vocab_pastime"],"primaryEvidenceTargetId":"vocab_pastime","languageBankContextId":"pastime_ctx_6"}'::jsonb,'live'),
('language-bank:feat_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"After two years of daily training, she completed the mountain run in under an hour, a ____ that she had earned through practice rather than chance.","acceptedAnswers":["feat"],"distractors":[{"text":"fluke","reason":"Fits grammatically, but a fluke is an accident, which contradicts earned through practice rather than chance."},{"text":"coincidence","reason":"Fits grammatically, but a coincidence happens by chance, which contradicts earned through practice rather than chance."},{"text":"gift","reason":"Fits grammatically, but a gift is something given, which contradicts earned through practice."}],"linkedVocabularyIds":["vocab_feat"],"primaryEvidenceTargetId":"vocab_feat","languageBankContextId":"feat_ctx_1"}'::jsonb,'live'),
('language-bank:feat_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Finishing the race with a broken ankle was a ____ that earned the runner a standing ovation from the whole stadium.","acceptedAnswers":["feat"],"distractors":[{"text":"flop","reason":"Fits grammatically, but a flop is a failure, which does not earn a standing ovation."},{"text":"blunder","reason":"Fits grammatically, but a blunder is a serious mistake, which does not earn a standing ovation."},{"text":"mistake","reason":"Fits grammatically, but a mistake is an error, which does not earn a standing ovation."}],"linkedVocabularyIds":["vocab_feat"],"primaryEvidenceTargetId":"vocab_feat","languageBankContextId":"feat_ctx_2"}'::jsonb,'live'),
('language-bank:feat_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Walking a tightrope between two skyscrapers was a ____ that left the whole crowd speechless with admiration.","acceptedAnswers":["feat"],"distractors":[{"text":"fear","reason":"Fits grammatically, but fear is a feeling the walker has, not something that leaves a crowd speechless with admiration."},{"text":"threat","reason":"Fits grammatically, but a threat is a danger, which does not cause speechless admiration."},{"text":"scandal","reason":"Fits grammatically, but a scandal causes shock and blame, not admiration."}],"linkedVocabularyIds":["vocab_feat"],"primaryEvidenceTargetId":"vocab_feat","languageBankContextId":"feat_ctx_3"}'::jsonb,'live'),
('language-bank:feat_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Reaching the summit in under five hours after only two months of training was a ____ that surprised even her coach.","acceptedAnswers":["feat"],"distractors":[{"text":"habit","reason":"Fits grammatically, but a habit is something done repeatedly, but reaching the summit once is a single achievement."},{"text":"custom","reason":"Fits grammatically, but a custom is a traditional way of behaving, but reaching the summit once is a single achievement."},{"text":"routine","reason":"Fits grammatically, but a routine is a regular set of actions, but reaching the summit once is a single achievement."}],"linkedVocabularyIds":["vocab_feat"],"primaryEvidenceTargetId":"vocab_feat","languageBankContextId":"feat_ctx_4"}'::jsonb,'live'),
('language-bank:feat_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Fixing the damaged roof in a single weekend was a remarkable ____, and the volunteers did it all for free.","acceptedAnswers":["feat"],"distractors":[{"text":"fee","reason":"Fits grammatically, but a fee is a payment, which contradicts the volunteers did it all for free."},{"text":"price","reason":"Fits grammatically, but a price is an amount paid, which contradicts the volunteers did it all for free."},{"text":"charge","reason":"Fits grammatically, but a charge is an amount asked for payment, which contradicts the volunteers did it all for free."}],"linkedVocabularyIds":["vocab_feat"],"primaryEvidenceTargetId":"vocab_feat","languageBankContextId":"feat_ctx_5"}'::jsonb,'live'),
('language-bank:feat_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Arranging a trip for three hundred students in one afternoon was quite a ____, and the teachers still talk about how smoothly it went.","acceptedAnswers":["feat"],"distractors":[{"text":"mess","reason":"Fits grammatically, but a mess is a badly handled situation, which contradicts how smoothly it went."},{"text":"muddle","reason":"Fits grammatically, but a muddle is a confused situation, which contradicts how smoothly it went."},{"text":"shambles","reason":"Fits grammatically, but a shambles is a disorganised failure, which contradicts how smoothly it went."}],"linkedVocabularyIds":["vocab_feat"],"primaryEvidenceTargetId":"vocab_feat","languageBankContextId":"feat_ctx_6"}'::jsonb,'live'),
('language-bank:regardless_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The match will take place ____ of the weather, so bring waterproof clothes just in case.","acceptedAnswers":["regardless"],"distractors":[{"text":"instead","reason":"Fits grammatically, but instead of the weather would mean the weather replaces the match, which does not fit bring waterproof clothes just in case."},{"text":"apart","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"irrelevant","reason":"Fits grammatically, but irrelevant of is not used in this pattern; the standard phrase is irrespective of or regardless of."}],"linkedVocabularyIds":["vocab_regardless"],"primaryEvidenceTargetId":"vocab_regardless","languageBankContextId":"regardless_ctx_1"}'::jsonb,'live'),
('language-bank:regardless_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Every student must attend training, ____ of their ability or experience, so beginners and the best players train together.","acceptedAnswers":["regardless"],"distractors":[{"text":"because","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"instead","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"nevertheless","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."}],"linkedVocabularyIds":["vocab_regardless"],"primaryEvidenceTargetId":"vocab_regardless","languageBankContextId":"regardless_ctx_2"}'::jsonb,'live'),
('language-bank:regardless_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Their best striker was injured, which was a good reason to stop, but the team carried on with the final ____ of the injury.","acceptedAnswers":["regardless"],"distractors":[{"text":"because","reason":"Fits grammatically, but because of the injury would make it the reason for carrying on, but the sentence calls it a good reason to stop."},{"text":"ahead","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"afterwards","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."}],"linkedVocabularyIds":["vocab_regardless"],"primaryEvidenceTargetId":"vocab_regardless","languageBankContextId":"regardless_ctx_3"}'::jsonb,'live'),
('language-bank:regardless_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The school offers a free place to every applicant, ____ of family income, so rich and poor families are treated the same.","acceptedAnswers":["regardless"],"distractors":[{"text":"because","reason":"Fits grammatically, but because of family income would make income the reason, but rich and poor families are treated the same."},{"text":"instead","reason":"This word does not give the meaning the sentence needs, so it cannot complete the sentence correctly."},{"text":"out","reason":"Fits grammatically, but out of family income does not fit the idea that income does not matter."}],"linkedVocabularyIds":["vocab_regardless"],"primaryEvidenceTargetId":"vocab_regardless","languageBankContextId":"regardless_ctx_4"}'::jsonb,'live'),
('language-bank:regardless_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"You must submit the report by Friday, ____ of whether you have finished the final section.","acceptedAnswers":["regardless"],"distractors":[{"text":"because","reason":"Fits grammatically, but because of whether you have finished would give a reason, whereas the sentence says it does not matter."},{"text":"instead","reason":"Fits grammatically, but instead of whether you have finished does not fit the idea that it does not matter."},{"text":"unaffected","reason":"Fits grammatically, but unaffected of is not used in this pattern; the standard phrase is regardless of."}],"linkedVocabularyIds":["vocab_regardless"],"primaryEvidenceTargetId":"vocab_regardless","languageBankContextId":"regardless_ctx_5"}'::jsonb,'live'),
('language-bank:regardless_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"He kept running, ____ of the pain in his knee and the cheers telling him to stop.","acceptedAnswers":["regardless"],"distractors":[{"text":"because","reason":"Fits grammatically, but because of the pain would make it the reason to keep running, but the cheers telling him to stop show he ignored them."},{"text":"in","reason":"Fits grammatically, but in of the pain is not a phrase; the standard phrase is regardless of."},{"text":"instead","reason":"Fits grammatically, but instead of the pain does not fit the idea of ignoring pain and cheers."}],"linkedVocabularyIds":["vocab_regardless"],"primaryEvidenceTargetId":"vocab_regardless","languageBankContextId":"regardless_ctx_6"}'::jsonb,'live'),
('language-bank:monetary_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The trophy has little ____ value, but it means a great deal to the winners.","acceptedAnswers":["monetary"],"distractors":[{"text":"momentary","reason":"Fits grammatically, but momentary means lasting a very short time, but value in this sentence is contrasted with what it means to the winners."},{"text":"military","reason":"Fits grammatically, but military relates to armed forces, which does not fit value of a trophy."},{"text":"monthly","reason":"Fits grammatically, but monthly means happening every month, which does not fit value of a trophy."}],"linkedVocabularyIds":["vocab_monetary"],"primaryEvidenceTargetId":"vocab_monetary","languageBankContextId":"monetary_ctx_1"}'::jsonb,'live'),
('language-bank:monetary_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Volunteers receive no ____ reward for helping at the tournament, only a free t-shirt.","acceptedAnswers":["monetary"],"distractors":[{"text":"mandatory","reason":"Fits grammatically, but mandatory means compulsory, which does not describe a reward."},{"text":"momentary","reason":"Fits grammatically, but momentary means lasting a very short time, which does not describe the kind of reward."},{"text":"military","reason":"This word cannot complete the sentence: it does not give a correct, natural meaning here."}],"linkedVocabularyIds":["vocab_monetary"],"primaryEvidenceTargetId":"vocab_monetary","languageBankContextId":"monetary_ctx_2"}'::jsonb,'live'),
('language-bank:monetary_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The club offered ____ support, giving each student a small payment toward travel costs.","acceptedAnswers":["monetary"],"distractors":[{"text":"moral","reason":"Fits grammatically, but moral support is encouragement, but giving each student a small payment is financial."},{"text":"military","reason":"Fits grammatically, but military relates to armed forces, which does not fit a small payment toward travel costs."},{"text":"momentary","reason":"Fits grammatically, but momentary means lasting a very short time, which does not describe a payment."}],"linkedVocabularyIds":["vocab_monetary"],"primaryEvidenceTargetId":"vocab_monetary","languageBankContextId":"monetary_ctx_3"}'::jsonb,'live'),
('language-bank:monetary_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Some prizes are ____: winners receive £10,000 in cash to spend as they choose, while medals and cups have no exchangeable financial value.","acceptedAnswers":["monetary"],"distractors":[{"text":"mandatory","reason":"Fits grammatically, but mandatory means compulsory, which does not describe £10,000 in cash."},{"text":"ceremonial","reason":"Fits grammatically, but ceremonial prizes are given for show, but £10,000 to spend as winners choose has substantial financial value."},{"text":"symbolic","reason":"Fits grammatically, but symbolic prizes only stand for something, but £10,000 to spend as winners choose has substantial financial value."}],"linkedVocabularyIds":["vocab_monetary"],"primaryEvidenceTargetId":"vocab_monetary","languageBankContextId":"monetary_ctx_4"}'::jsonb,'live'),
('language-bank:monetary_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The study found that happiness depends only partly on ____ gain, such as a higher salary or a lottery win; friends and health matter more.","acceptedAnswers":["monetary"],"distractors":[{"text":"momentary","reason":"Fits grammatically, but momentary means lasting a very short time, which does not describe a higher salary or a lottery win."},{"text":"moral","reason":"Fits grammatically, but moral relates to right and wrong, which does not describe a higher salary or a lottery win."},{"text":"mental","reason":"Fits grammatically, but mental relates to the mind, which does not describe a higher salary or a lottery win."}],"linkedVocabularyIds":["vocab_monetary"],"primaryEvidenceTargetId":"vocab_monetary","languageBankContextId":"monetary_ctx_5"}'::jsonb,'live'),
('language-bank:monetary_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The high ____ cost of the stadium, nearly two hundred million pounds, made the council decide to share it with a neighbouring town.","acceptedAnswers":["monetary"],"distractors":[{"text":"moral","reason":"Fits grammatically, but moral relates to right and wrong, which does not describe a cost of nearly two hundred million pounds."},{"text":"mental","reason":"Fits grammatically, but mental relates to the mind, which does not describe a cost of nearly two hundred million pounds."},{"text":"mandatory","reason":"Fits grammatically, but mandatory means compulsory, which does not describe a cost of nearly two hundred million pounds."}],"linkedVocabularyIds":["vocab_monetary"],"primaryEvidenceTargetId":"vocab_monetary","languageBankContextId":"monetary_ctx_6"}'::jsonb,'live'),
('language-bank:estimated_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The ____ crowd at the final was fifty thousand, though officials admitted that nobody had counted exactly.","acceptedAnswers":["estimated"],"distractors":[{"text":"exact","reason":"Fits grammatically, but exact contradicts nobody had counted exactly."},{"text":"confirmed","reason":"Fits grammatically, but confirmed means checked and certain, which contradicts nobody had counted exactly."},{"text":"registered","reason":"Fits grammatically, but registered would mean recorded one by one, which contradicts nobody had counted exactly."}],"linkedVocabularyIds":["vocab_estimated"],"primaryEvidenceTargetId":"vocab_estimated","languageBankContextId":"estimated_ctx_1"}'::jsonb,'live'),
('language-bank:estimated_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The ____ cost of the new stadium is two hundred million pounds, but the final bill may be higher.","acceptedAnswers":["estimated"],"distractors":[{"text":"exact","reason":"Fits grammatically, but exact contradicts the final bill may be higher."},{"text":"actual","reason":"Fits grammatically, but actual means the real figure, but the final bill may be higher shows this figure is not final."},{"text":"guaranteed","reason":"Fits grammatically, but guaranteed means promised, which contradicts the final bill may be higher."}],"linkedVocabularyIds":["vocab_estimated"],"primaryEvidenceTargetId":"vocab_estimated","languageBankContextId":"estimated_ctx_2"}'::jsonb,'live'),
('language-bank:estimated_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The ____ figure of about three thousand visitors a day was published by officials, though nobody knew the true number.","acceptedAnswers":["estimated"],"distractors":[{"text":"exact","reason":"Fits grammatically, but exact contradicts nobody knew the true number."},{"text":"confirmed","reason":"Fits grammatically, but confirmed means proved to be true, which contradicts nobody knew the true number."},{"text":"counted","reason":"Fits grammatically, but a counted figure comes from counting every visitor, which contradicts nobody knew the true number."}],"linkedVocabularyIds":["vocab_estimated"],"primaryEvidenceTargetId":"vocab_estimated","languageBankContextId":"estimated_ctx_3"}'::jsonb,'live'),
('language-bank:estimated_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The ____ distance of the race is ten kilometres, but the course has not yet been measured.","acceptedAnswers":["estimated"],"distractors":[{"text":"exact","reason":"Fits grammatically, but exact contradicts the course has not yet been measured."},{"text":"measured","reason":"Fits grammatically, but measured contradicts the course has not yet been measured."},{"text":"certified","reason":"Fits grammatically, but certified means officially checked and confirmed, which contradicts the course has not yet been measured."}],"linkedVocabularyIds":["vocab_estimated"],"primaryEvidenceTargetId":"vocab_estimated","languageBankContextId":"estimated_ctx_4"}'::jsonb,'live'),
('language-bank:estimated_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Because the exact date cannot be known, scientists can only give ____ ages for the fossil.","acceptedAnswers":["estimated"],"distractors":[{"text":"exact","reason":"Fits grammatically, but exact contradicts the exact date cannot be known."},{"text":"precise","reason":"Fits grammatically, but precise means exact, which contradicts the exact date cannot be known."},{"text":"pinpoint","reason":"Fits grammatically, but pinpoint means exact to a particular point, which contradicts the exact date cannot be known."}],"linkedVocabularyIds":["vocab_estimated"],"primaryEvidenceTargetId":"vocab_estimated","languageBankContextId":"estimated_ctx_5"}'::jsonb,'live'),
('language-bank:estimated_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Her ____ finishing time is two hours, but it depends on the weather on the day.","acceptedAnswers":["estimated"],"distractors":[{"text":"final","reason":"Fits grammatically, but final means no longer able to change, but it depends on the weather shows it can change."},{"text":"confirmed","reason":"Fits grammatically, but confirmed means checked and certain, but it depends on the weather shows it is only a guess."},{"text":"recorded","reason":"Fits grammatically, but recorded means already measured, but it depends on the weather shows it has not happened yet."}],"linkedVocabularyIds":["vocab_estimated"],"primaryEvidenceTargetId":"vocab_estimated","languageBankContextId":"estimated_ctx_6"}'::jsonb,'live'),
